// Reservas: guarda la mesa elegida y avisa si ya está ocupada.
// Sin librerías externas: solo JavaScript estándar.

const AFORO_POR_MESA = 4;

/**
 * Comprueba si una mesa admite a un grupo.
 * @param {{ ocupada: boolean, plazas: number }} mesa
 * @param {number} personas
 */
export function admiteGrupo(mesa, personas) {
  if (mesa.ocupada) return false;
  return personas <= (mesa.plazas || AFORO_POR_MESA);
}

export async function reservar(mesa, datos) {
  const respuesta = await fetch('/api/reservas', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ mesa: mesa.id, ...datos })
  });
  if (!respuesta.ok) throw new Error('No se pudo reservar');
  return respuesta.json();
}

// Carrito persistente en localStorage (con try/catch:
// en modo privado el navegador puede negarse).
const CLAVE = 'carrito-v1';

export function leer() {
  try {
    return JSON.parse(localStorage.getItem(CLAVE)) ?? [];
  } catch {
    return [];
  }
}

export function guardar(lineas) {
  try { localStorage.setItem(CLAVE, JSON.stringify(lineas)); } catch { /* sin espacio */ }
}

