import * as THREE from 'three';

// Escena del producto: luz suave, sombra de contacto
// y render solo cuando algo cambia.
export function crearEscena(lienzo) {
  const renderer = new THREE.WebGLRenderer({ canvas: lienzo, antialias: true });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));

  const escena = new THREE.Scene();
  const camara = new THREE.PerspectiveCamera(35, 1, 0.1, 50);
  camara.position.set(0, 1.2, 4);

  let pendiente = true;
  const pedirRender = () => { pendiente = true; };

  renderer.setAnimationLoop(() => {
    if (!pendiente || document.hidden) return;
    renderer.render(escena, camara);
    pendiente = false;
  });
  return { escena, camara, pedirRender };
}

// Opciones del configurador: añadir un acabado = añadir una línea.
export const ACABADOS = [
  { id: 'roble',  nombre: 'Roble natural', color: '#c8a27a', precio: 0 },
  { id: 'nogal',  nombre: 'Nogal',         color: '#6b4a32', precio: 40 },
  { id: 'lacado', nombre: 'Lacado blanco', color: '#f2f0eb', precio: 65 }
];

export function precioFinal(base, idAcabado) {
  const acabado = ACABADOS.find(a => a.id === idAcabado);
  return base + (acabado ? acabado.precio : 0);
}

// Informe diario: suma las ventas y avisa por correo.
// Las claves van en variables de entorno, nunca en el código.
import { leerVentas } from './fuentes/ventas.mjs';
import { enviarCorreo } from './avisos/correo.mjs';

const hoy = new Date().toISOString().slice(0, 10);
const ventas = await leerVentas(hoy);

const total = ventas.reduce((suma, v) => suma + v.importe, 0);
const texto = `Ventas del ${hoy}: ${ventas.length} pedidos, ${total.toFixed(2)} €`;

await enviarCorreo({ asunto: 'Resumen del día', texto });
console.log('Informe enviado:', texto);

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { admiteGrupo } from '../src/js/reservas.js';

test('una mesa ocupada no admite grupos', () => {
  assert.equal(admiteGrupo({ ocupada: true, plazas: 4 }, 2), false);
});

test('una mesa libre admite hasta su aforo', () => {
  assert.equal(admiteGrupo({ ocupada: false, plazas: 4 }, 4), true);
  assert.equal(admiteGrupo({ ocupada: false, plazas: 4 }, 5), false);
});

import { test } from 'node:test';
